CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_key varchar(512) UNIQUE NOT NULL, title text NOT NULL, description text, organizer text, start_date timestamptz NOT NULL, end_date timestamptz, timezone varchar(64) NOT NULL DEFAULT 'America/Chicago', venue_name text, street_address text, neighborhood text, city varchar(100) NOT NULL DEFAULT 'Chicago', state varchar(32) NOT NULL DEFAULT 'IL', latitude double precision, longitude double precision, categories jsonb NOT NULL DEFAULT '[]', tags jsonb NOT NULL DEFAULT '[]', is_free boolean, price_min double precision, price_max double precision, currency varchar(3), registration_url text NOT NULL, source_url text NOT NULL, source_name text NOT NULL, image_url text, relevance_score integer NOT NULL DEFAULT 0, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), last_verified_at timestamptz, status varchar(16) NOT NULL DEFAULT 'active', extraction_confidence integer NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS events_start_date_idx ON events(start_date); CREATE INDEX IF NOT EXISTS events_status_idx ON events(status); CREATE INDEX IF NOT EXISTS events_score_idx ON events(relevance_score); CREATE INDEX IF NOT EXISTS events_city_idx ON events(city); CREATE INDEX IF NOT EXISTS events_categories_idx ON events USING gin(categories); CREATE INDEX IF NOT EXISTS events_search_idx ON events USING gin(to_tsvector('english', title || ' ' || coalesce(description,'')));
CREATE TABLE IF NOT EXISTS event_source_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, source_id text NOT NULL, external_id text, source_url text NOT NULL, discovered_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id, external_id));
CREATE TABLE IF NOT EXISTS event_sources (id text PRIMARY KEY, name text NOT NULL, status text NOT NULL, last_success_at timestamptz, last_error text, config jsonb DEFAULT '{}');
CREATE TABLE IF NOT EXISTS ingestion_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, status text NOT NULL, sources_attempted integer NOT NULL DEFAULT 0, discovered integer NOT NULL DEFAULT 0, inserted integer NOT NULL DEFAULT 0, updated integer NOT NULL DEFAULT 0, duplicates integer NOT NULL DEFAULT 0, errors integer NOT NULL DEFAULT 0, lock_token text);
CREATE TABLE IF NOT EXISTS ingestion_errors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES ingestion_runs(id), source_id text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), anonymous_id varchar(128) UNIQUE, interests jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
